#!/usr/bin/env python3
import os
import sys
import json
import time
import urllib.request
import urllib.error

API_BASE = os.environ.get("API_BASE", "http://127.0.0.1:8080")
CONFIG_FILE = "/app/client_config.json"

# Defaults are chosen to complete the 1000-record maintenance backfill well
# within 3 minutes while staying inside the documented API limits.
DEFAULT_CONFIG = {
    "max_rps": 2,          # GET /enrich documented limit
    "use_batch": True,    # POST /batch_enrich is required for 1000 records < 3 min
    "batch_size": 100,    # documented maximum batch size
    "batch_max_rps": 4    # under the documented 5 rps limit, with safety margin
}


def load_config():
    config = DEFAULT_CONFIG.copy()
    if os.path.exists(CONFIG_FILE):
        with open(CONFIG_FILE, "r") as f:
            config.update(json.load(f))
    return config


def _positive_int(value, default, minimum=1, maximum=None):
    try:
        value = int(value)
    except (TypeError, ValueError):
        value = default
    value = max(minimum, value)
    if maximum is not None:
        value = min(maximum, value)
    return value


def _positive_float(value, default, minimum=0.1, maximum=None):
    try:
        value = float(value)
    except (TypeError, ValueError):
        value = default
    value = max(minimum, value)
    if maximum is not None:
        value = min(maximum, value)
    return value


def _read_json_response(req, timeout=10, retries=3):
    """Open a request and decode JSON, retrying transient API throttling/errors."""
    for attempt in range(retries):
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            retryable = exc.code in (429, 500, 502, 503, 504)
            if not retryable or attempt >= retries - 1:
                raise
            retry_after = exc.headers.get("Retry-After")
            try:
                delay = float(retry_after) if retry_after else 0.5 * (2 ** attempt)
            except ValueError:
                delay = 0.5 * (2 ** attempt)
            time.sleep(min(delay, 5.0))
        except urllib.error.URLError:
            if attempt >= retries - 1:
                raise
            time.sleep(0.5 * (2 ** attempt))


def fetch_single(record_id: int) -> dict:
    url = f"{API_BASE}/enrich?record_id={record_id}"
    req = urllib.request.Request(url, headers={"User-Agent": "BackfillTool/1.0"})
    return _read_json_response(req)


def fetch_batch(record_ids: list) -> list:
    url = f"{API_BASE}/batch_enrich"
    payload = json.dumps({"record_ids": record_ids}).encode("utf-8")
